effect.shader:
void main() {
    vec2 uv = acScreenNorm;
    vec2 d = uv - center;
    float dist = length(d);
    vec2 dir = dist > 0.0001 ? d / dist : vec2(0.0);

    int N = int(samples);
    vec3 acc = vec3(0.0);
    float a = 0.0;
    for (int i = 0; i < 16; i++) {
        if (i >= N) break;
        float t = float(i) / float(N - 1);
        float offR = strength * dist * (0.6 + 0.4 * t);
        float offG = strength * dist * 0.5 * t;
        float offB = -strength * dist * (0.6 + 0.4 * t);
        vec4 cr = texture(inputImg, uv + dir * offR);
        vec4 cg = texture(inputImg, uv + dir * offG);
        vec4 cb = texture(inputImg, uv + dir * offB);
        acc += vec3(cr.r, cg.g, cb.b);
        a += cg.a;
    }
    fragColor = vec4(acc / float(N), a / float(N));
}
